import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.Ky-Ipuyb.js";const k=JSON.parse('{"title":"Development Guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/sfml/development.md"},"headers":[],"relativePath":"guide/development.md","filePath":"guide/development.md"}'),n={name:"guide/development.md"};function d(o,e,r,l,p,h){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="development-guide" tabindex="-1">Development Guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to &quot;Development Guide&quot;">​</a></h1><blockquote><p>This guide is for contributors changing source code, maintaining documentation or running repository tests. To use sfml.js as a dependency, start with <a href="/guide/getting-started">Quick start</a>.</p></blockquote><p><a href="/guide/">Documentation</a> · <a href="/guide/api">API guide</a> · <a href="/examples">Examples</a></p><p><a id="get-the-source"></a></p><h2 id="get-the-source" tabindex="-1">Get the source <a class="header-anchor" href="#get-the-source" aria-label="Permalink to &quot;Get the source&quot;">​</a></h2><p>Prepare Node.js, Python and a C++20 toolchain; see <a href="/guide/getting-started#requirements">requirements</a> for platform installation commands. Then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XadillaX/node-sfml.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-sfml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span></code></pre></div><p><code>node tools/bootstrap.cjs</code> installs dependencies with Rush and builds interop, both bindings and the website in dependency order. SFML and ImGui libraries are downloaded by their owning packages. Node.js 20 or 22 is recommended for this checkout; the website requires Node.js 20 or later.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>Run these commands from the repository root:</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>npm --prefix packages/sfml.js run build</code></td><td>Compile native code and TypeScript</td></tr><tr><td><code>npm --prefix packages/sfml.js run build:native</code></td><td>Compile native code and update clangd configuration</td></tr><tr><td><code>npm --prefix packages/sfml.js run build:ts</code></td><td>Generate constants and compile TypeScript</td></tr><tr><td><code>npm --prefix site run build</code></td><td>Build the four-language website and generated API reference</td></tr><tr><td><code>npm --prefix site run build:reference</code></td><td>Generate TypeDoc API documentation only</td></tr><tr><td><code>npm --prefix site run dev</code></td><td>Preview the website during development</td></tr><tr><td><code>npm --prefix site run preview</code></td><td>Serve the production website build locally</td></tr><tr><td><code>npm --prefix packages/sfml.js run lint</code></td><td>Check source, tools, tests and examples</td></tr><tr><td><code>npm --prefix packages/sfml.js run test:types</code></td><td>Validate TypeScript APIs</td></tr><tr><td><code>npm --prefix packages/sfml.js run test:runtime</code></td><td>Run runtime tests serially; requires a prior build</td></tr><tr><td><code>npm --prefix packages/sfml.js test</code></td><td>Run lint, build, type checks and runtime tests in sequence</td></tr><tr><td><code>npm --prefix packages/sfml.js pack --dry-run</code></td><td>Inspect the npm package file list</td></tr></tbody></table><p>For TypeScript-only changes, run <code>npm --prefix packages/sfml.js run build:ts</code>; after native changes, run <code>npm --prefix packages/sfml.js run build</code>. Runtime tests do not rebuild automatically, so ensure the build matches the source before running them.</p><p><a id="testing"></a></p><h2 id="testing-and-verification" tabindex="-1">Testing and verification <a class="header-anchor" href="#testing-and-verification" aria-label="Permalink to &quot;Testing and verification&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p><code>npm --prefix packages/sfml.js test</code> runs lint, native and TypeScript builds, type checks and runtime tests.</p><p>Runtime tests run serially by file, covering public APIs, comparisons with native SFML, actual rendered pixels, asynchronous I/O, snapshots and lifetimes. Type tests are in <code>test/*.types.ts</code>, runtime tests in <code>test/*.test.cjs</code>, and native comparisons in <code>test/native/</code>.</p><p>Graphics tests require a display server and an OpenGL context. For headless Linux, install Xvfb as shown in <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/node.js.yml" target="_blank" rel="noreferrer">Linux CI</a>, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LIBGL_ALWAYS_SOFTWARE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  xvfb-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-screen 0 1280x1024x24 -noreset&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:runtime</span></span></code></pre></div><p>CI is configured for Node.js 20/22 on Linux, macOS and Windows; <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/node.js-windows.yml" target="_blank" rel="noreferrer">Windows CI</a> uses Mesa software OpenGL.</p><p>CI does not replace device testing for speakers, microphones, joysticks, sensors or fullscreen switching. SFML&#39;s macOS backend does not support Vulkan, and SuspendAwareClock.now supports only Android. State the actual platform and skipped cases when reporting results.</p><h2 id="maintaining-documentation" tabindex="-1">Maintaining documentation <a class="header-anchor" href="#maintaining-documentation" aria-label="Permalink to &quot;Maintaining documentation&quot;">​</a></h2><p>The package README files introduce each package. Root <code>docs/sfml/</code>, <code>docs/imgui/</code> and <code>docs/interop/</code> contain the guides. Runnable examples and API source comments stay in their owning packages. Root <code>site/</code> is the private Rush project <code>sfml-js-site</code> and owns VitePress, TypeDoc, localization and site tests.</p><ul><li>Examples import the public <code>sfml.js</code> package; only repository demo scripts use repository-relative paths.</li><li>Distinguish complete examples from context-dependent snippets, and state requirements for async functions, assets and devices.</li><li>Check loading booleans and network statuses, and close owned resources when examples end.</li><li>When changing public behavior, update JSDoc, the relevant guides and affected examples together.</li></ul><p>Install the website dependencies, then build the website:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> common/scripts/install-run-rush.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sfml-js-site</span></span></code></pre></div><p>After bootstrap, <code>npm --prefix site run dev</code> prepares Markdown and serves the site. Restart it after changing guide sources; theme changes support hot reload. <code>npm --prefix site run build</code> generates the complete site in <code>site/build/site/</code>. Core URLs remain <code>/guide</code>, <code>/examples</code> and <code>/reference</code>; ImGui uses <code>/imgui/</code> and <code>/reference/imgui/</code>, and native extension guidance uses <code>/interop/</code>. Each has Chinese, Japanese and Korean counterparts.</p><p><code>npm --prefix site test</code> checks routes, localization and theme behavior. The site build also checks all generated links, anchors, language coverage and assets. <code>npm --prefix site run build:reference</code> regenerates both API references in <code>site/build/site/reference/</code> and its language counterparts. TypeDoc reads package source comments and requires complete translations. ImGui API translations are maintained beside their declarations.</p><p>The <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/publish-docs.yml" target="_blank" rel="noreferrer">Publish Docs workflow</a> runs on updates to <code>main</code> and also supports manual dispatch. Generated output is committed to <code>docs/</code> on the <code>gh-pages</code> branch, preserving files at that branch&#39;s root and its existing <code>CNAME</code> (<code>sfml.js.org</code>). It skips the commit when generated content is unchanged.</p><p>Legacy TypeDoc class and interface URLs redirect to the corresponding English reference page, preserving fragment links. The API language selector preserves the current page and member anchor.</p><p>Write JSDoc in English first, followed by <code>@zh</code>, <code>@ja</code> and <code>@ko</code> translations. Place each translation immediately after its summary or block tag. Parameter translations use <code>@zh name - description</code> (likewise for Japanese and Korean). Keep identifiers, code examples and links intact. Missing prose translations fail the documentation build.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * Read the elapsed time.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@zh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 读取经过的时间。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ja</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 経過時間を読み取ります。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ko</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 경과 시간을 읽습니다.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@param</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> - Time unit.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@zh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 时间单位。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ja</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 時間の単位。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ko</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 시간 단위.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> */</span></span></code></pre></div><p>Generated constant descriptions are maintained in <code>tools/constant-docs.json</code> and the templates in <code>tools/constant-docs.cjs</code>. Run <code>npm --prefix packages/sfml.js run generate:window</code> and <code>npm --prefix packages/sfml.js run generate:network</code> after editing them; do not edit generated comments directly.</p><h2 id="running-examples" tabindex="-1">Running examples <a class="header-anchor" href="#running-examples" aria-label="Permalink to &quot;Running examples&quot;">​</a></h2><p>Run these commands from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:types</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=120</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:window</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=120</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:audio</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:network</span></span></code></pre></div><p>The examples are organized into <a href="/examples">overview</a>, <a href="/examples/features">feature examples</a>, <a href="/examples/official">official examples</a> and <a href="/examples/projects">games and applications</a>. Commands and <a href="/examples/features#screenshots">screenshot support</a> are documented with their entry points. After building, run the script directly; pass <code>--frames</code> only where supported.</p><h2 id="source-and-generated-files" tabindex="-1">Source and generated files <a class="header-anchor" href="#source-and-generated-files" aria-label="Permalink to &quot;Source and generated files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Contents</th></tr></thead><tbody><tr><td><code>packages/sfml.js/</code></td><td>Core source, native binding, tests and examples</td></tr><tr><td><code>packages/sfml.js-imgui/</code></td><td>ImGui binding source, multilingual API comments and demo</td></tr><tr><td><code>packages/sfml.js-interop/</code></td><td>Shared headers and SFML SDK downloader</td></tr><tr><td><code>docs/</code></td><td>Shared guides, grouped by package</td></tr><tr><td><code>site/</code></td><td>VitePress, TypeDoc, theme and site tests</td></tr><tr><td><code>common/</code></td><td>Rush configuration and shared lockfile</td></tr></tbody></table><p><code>build/</code>, <code>dist/</code>, <code>node_modules/</code> and downloaded SFML libraries are generated content. Window and network constants are generated from the current SFML headers; do not edit <code>src/*/gen/constants.ts</code> directly.</p><p>Native builds generate per-package compilation databases and merge them into root <code>compile_commands.json</code>, used by root <code>.clangd</code>. <code>node tools/configure-lsp.cjs</code> merges existing databases without rebuilding native code.</p><h2 id="implementation-conventions" tabindex="-1">Implementation conventions <a class="header-anchor" href="#implementation-conventions" aria-label="Permalink to &quot;Implementation conventions&quot;">​</a></h2><p>Value types use TypedArray for calculations and shared storage; native resources and their views keep memory alive. Graphics resources are destroyed on their owning thread. Recorded draws must preserve snapshot semantics: later property changes must not alter previously recorded results.</p><p>Relevant entry points include <code>src/internal/lazy-value.ts</code>, <code>src/internal/graphics-state.ts</code>, <code>packages/sfml.js-interop/include/shared-handle.h</code>, <code>native/deferred-delete.h</code> and <code>native/batch-drawable.h</code>. Add JSDoc describing behavior, parameters and upstream counterparts when adding public fields or methods.</p><p>The downloader, installation hooks and platform builds are interconnected; validate the corresponding platforms when changing them. Download URLs and architecture mappings are in <code>packages/sfml.js-interop/tools/lib_downloader_urls.cjs</code>, and the cache is in <code>packages/sfml.js-interop/third_party/sfml/</code>.</p><h2 id="submitting-changes" tabindex="-1">Submitting changes <a class="header-anchor" href="#submitting-changes" aria-label="Permalink to &quot;Submitting changes&quot;">​</a></h2><p>Describe the specific behavior, relevant verification and unverified platform paths in the PR. Run affected native comparison tests for native changes; check links, code examples and the TypeDoc build for documentation-only changes. Include the machine, Node.js/SFML versions, scenario and measurement method with performance figures.</p><h3 id="record-changes-with-rush-change" tabindex="-1">Record changes with rush change <a class="header-anchor" href="#record-changes-with-rush-change" aria-label="Permalink to &quot;Record changes with rush change&quot;">​</a></h3><p>Package versions are placeholders managed by Rush version policies; do not edit <code>version</code> fields in <code>package.json</code> by hand. All three published packages (<code>sfml.js-interop</code>, <code>sfml.js</code>, and <code>sfml.js-imgui</code>) use the single lockstep policy <code>sfml-js</code>, so they always release together and share one version number.</p><p>After changing a published package, run from the repository root and commit the generated file under <code>common/changes/</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> common/scripts/install-run-rush.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> change</span></span></code></pre></div><p>Choose <code>patch</code>, <code>minor</code> or <code>major</code> per affected package. Change files feed the CHANGELOG content; the lockstep policy&#39;s <code>nextBump</code> decides the actual version, and every release bumps and publishes all three packages together.</p><h3 id="release-through-ci" tabindex="-1">Release through CI <a class="header-anchor" href="#release-through-ci" aria-label="Permalink to &quot;Release through CI&quot;">​</a></h3><p>Releases run in the <strong>Publish packages</strong> workflow and must be cut only after main CI is green:</p><ol><li><p>Merge the PRs containing the <code>common/changes/*.json</code> files.</p></li><li><p>Push a <code>v*</code> tag at the main commit (the tag name only triggers the workflow; the version is determined by the lockstep policy):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2026.11.09</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2026.11.0</span></span></code></pre></div></li><li><p>The workflow builds and reruns all three packages&#39; tests, then <code>rush publish --apply --publish --target-branch main</code> applies the change files, updates versions and CHANGELOG files, merges the bump back to main, tags each package and publishes to npm.</p></li></ol><p>Requirements: an npm automation/publish token stored as the <code>NPM_AUTH_TOKEN</code> repository secret (consumed through <code>common/config/rush/.npmrc-publish</code>), and main must accept the workflow&#39;s <code>GITHUB_TOKEN</code> pushes. Internal dependencies between the three packages keep caret ranges in both the checked-in source and the published manifests; because every lockstep release shares one version number, the ranges always resolve to that exact version.</p>`,56)])])}const g=s(n,[["render",d]]);export{k as __pageData,g as default};
